-- Independent transaction: exercise financial constraints and the exposed role ACLs.
begin;
select test_assert(not has_table_privilege('authenticated','table_checks','update'),'staff cannot directly edit checks');
select test_assert(not has_table_privilege('service_role','check_settlements','insert'),'even API service cannot fabricate settlements');
select test_assert(not has_table_privilege('anon','registration_requests','insert'),'public cannot bypass rate-limited registration API');
select test_assert(not has_table_privilege('authenticated','registration_requests','select'),'tenant users cannot read applications');
select test_assert(not has_table_privilege('authenticated','platform_audit_logs','select'),'tenant users cannot read platform audit');
select test_assert(not has_function_privilege('authenticated','review_registration(text,uuid,uuid,uuid,uuid,integer,text)','execute'),'tenant users cannot approve through RPC');
select test_assert(not has_function_privilege('authenticated','activate_registration(uuid)','execute'),'tenant users cannot self-activate');
select test_assert(not has_function_privilege('anon','settle_check(uuid,uuid,integer,text,text,bigint,text)','execute'),'guest cannot settle');
select test_assert((select count(*)=count(distinct (tenant_id,table_id)) from table_checks where state='open'),'at most one open check for each table');
select test_assert(not exists(select 1 from orders o left join table_checks c on (c.tenant_id,c.id,c.table_id)=(o.tenant_id,o.check_id,o.table_id) where c.id is null),'every order points to same-tenant same-table check');
select test_error($q$insert into table_checks(tenant_id,table_id,visit_version,currency) values('40000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000002',50,'TRY')$q$,'23503');
select test_error($q$insert into check_settlements(tenant_id,check_id,request_key,action,amount_minor,currency,actor_id) select '40000000-0000-0000-0000-000000000002',id,'bad','pay',0,'TRY','50000000-0000-0000-0000-000000000001' from table_checks where tenant_id='40000000-0000-0000-0000-000000000001' limit 1$q$,'23503');
select test_error($q$update orders set total_minor=1$q$,'ORDER_SNAPSHOT_IMMUTABLE');
update orders set status='served';
set local role authenticated;
set local request.jwt.claim.sub='50000000-0000-0000-0000-000000000001';
select test_error($q$select read_table_checks('40000000-0000-0000-0000-000000000002')$q$,'42501');
select test_assert(jsonb_array_length(read_table_checks('40000000-0000-0000-0000-000000000001'))=2,'staff can read their floor');
select settle_check(c.tenant_id,c.id,c.version,'sql-payment','pay',(select sum(total_minor) from orders where check_id=c.id and tenant_id=c.tenant_id)) from table_checks c where c.tenant_id='40000000-0000-0000-0000-000000000001' and c.table_id='40000000-0000-0000-0000-000000000001';
select test_assert((select count(*)=1 from check_settlements),'authorized payment creates one settlement');
select settle_check(c.tenant_id,c.id,1,'sql-payment','pay',c.settled_total_minor) from table_checks c where c.tenant_id='40000000-0000-0000-0000-000000000001' and c.table_id='40000000-0000-0000-0000-000000000001';
select test_assert((select count(*)=1 from check_settlements),'same payment key replays without duplication');
select test_error($q$select settle_check(c.tenant_id,c.id,c.version,'different-payment','pay',c.settled_total_minor) from table_checks c where c.tenant_id='40000000-0000-0000-0000-000000000001' and c.table_id='40000000-0000-0000-0000-000000000001'$q$,'SETTLEMENT_CONFLICT');
reset role;
select test_assert((select visit_version=2 from dining_tables where tenant_id='40000000-0000-0000-0000-000000000001' and id='40000000-0000-0000-0000-000000000001'),'settlement advances visit exactly once');
select test_error($q$update check_settlements set amount_minor=0$q$,'SETTLEMENT_IMMUTABLE');
select test_error($q$delete from check_settlements$q$,'SETTLEMENT_IMMUTABLE');
select test_error($q$update orders set status='cancelled' where tenant_id='40000000-0000-0000-0000-000000000001'$q$,'CHECK_CLOSED');
rollback;
